     1→/**
     2→ * Value Score Types
     3→ * Types for the ticket valuation algorithm
     4→ */
     5→
     6→import type { NormalizedListing } from '../../adapters/base/platform-adapter.interface.js';
     7→
     8→// ============================================================================
     9→// Scoring Configuration
    10→// ============================================================================
    11→
    12→/**
    13→ * Weights for each component of the Value Score (must sum to 1.0)
    14→ */
    15→export interface ValueScoreWeights {
    16→  /** How price compares to current market average (35%) */
    17→  priceVsAverage: number;
    18→
    19→  /** Quality of the section based on venue data (25%) */
    20→  sectionQuality: number;
    21→
    22→  /** Position within the section - front rows score higher (15%) */
    23→  rowPosition: number;
    24→
    25→  /** How price compares to historical data (15%) */
    26→  historicalPricing: number;
    27→
    28→  /** Predicted resale potential (10%) */
    29→  resalePotential: number;
    30→}
    31→
    32→export const DEFAULT_WEIGHTS: ValueScoreWeights = {
    33→  priceVsAverage: 0.35,
    34→  sectionQuality: 0.25,
    35→  rowPosition: 0.15,
    36→  historicalPricing: 0.15,
    37→  resalePotential: 0.10,
    38→};
    39→
    40→// ============================================================================
    41→// Section Quality Types
    42→// ============================================================================
    43→
    44→/**
    45→ * Section tier classification for venues
    46→ * Lower number = better section
    47→ */
    48→export enum SectionTier {
    49→  /** Floor, VIP, Club Level */
    50→  PREMIUM = 1,
    51→
    52→  /** Lower bowl center sections */
    53→  UPPER_PREMIUM = 2,
    54→
    55→  /** Lower bowl sides, upper bowl center */
    56→  MID_TIER = 3,
    57→
    58→  /** Upper bowl sides, balcony */
    59→  UPPER_LEVEL = 4,
    60→
    61→  /** Limited view, behind stage, obstructed */
    62→  OBSTRUCTED = 5,
    63→}
    64→
    65→// ============================================================================
    66→// Historical Price Data
    67→// ============================================================================
    68→
